mary writer.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p438606698"],"reference":"work:1551","checked_at":"2026-11-02T21:06:36.091Z","canonical_name_resolution":"KB person p084696214/Q2346051 exactly matches cached selected source person OL371169A/Q2346051. Francine is the public author credit; Eclaire Francine Marie is the authority name. Exact2023ISBN9789021475899 is separate from publisher’s current2025ISBN9789062225866; do not replace the exact edition with that current offer. Annet Schaap illustrates, not a second primary writer."},{"type":"original_substantive_source_review","review":"content-review-015.json","sources":["https://www.singeluitgeverijen.nl/volt/boek/hoe-overleef-ik-alles-wat-ik-niemand-vertel/","https://openlibrary.org/works/OL36883768W","https://data.bibliotheken.nl/id/nbt/p438606698"]},{"type":"cover_front_review","sha256":"9d54afb205acc1c19c1c2181a8e83c4d95273cfc439d23d1d2489ef27e0331f4","cover_id":14534359,"reference":"cover-semantic-review-002.json","limitation":"Front and source-edition binding; no barcode or exact-printing-year assertion."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.singeluitgeverijen.nl/volt/boek/hoe-overleef-ik-alles-wat-ik-niemand-vertel/","reviewed_at":"2026-11-02T21:06:36.091+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-014","review_status":"approved","bound_author_id":987313003}'::jsonb as exact union all select 'catalog_edition_metadata:4' as ref,(select to_jsonb(t) from public.catalog_edition_metadata t where t.edition_id=987213002)='{"format":"hardcover","work_id":987113002,"evidence":[{"note":"KB person p084696214/Q2346051 exactly matches cached selected source person OL371169A/Q2346051. Francine is the public author credit; Eclaire Francine Marie is the authority name. Exact2023ISBN9789021475899 is separate from publisher’s current