as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987113007 and t.language='nl')='{"text":"Harry Haller voelt zich een buitenstaander in een samenleving waarvan de genoegens hem weinig zeggen. Zijn eenzaamheid en innerlijke verdeeldheid brengen hem steeds verder van anderen af. Een onverwachte ontmoeting opent mogelijkheden die hij eerder niet voor zichzelf zag. Hij wordt uitgedaagd anders om te gaan met plezier, contact en zijn eigen tegenstrijdigheden. Hermann Hesse volgt een man die zijn identiteit als afzonderlijke, lijdende geest ter discussie moet stellen zonder daar een eenvoudig antwoord op te vinden.","work_id":987113007,"evidence":[{"note":"Hermann Hesse source person OL76437A and exact-ISBN KB authority p068404956 share Wikidata Q25973, ISNI0000000121296240 and VIAF41841418. This resolves Hermann/Hermann Karl without name-only matching. Exact DeSteppewolf paperback9789023411239; existing Work retained.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p078216117","http://data.bibliotheken.nl/id/nbt/p085356573","http://data.bibliotheken.nl/id/nbt/p371614406","http://data.bibliotheken.nl/id/nbt/p830736387","http://data.bibliotheken.nl/id/nbt/p841089167"],"reference":"work:5208","checked_at":"2026-11-02T21:06:36.091Z","canonical_name_resolution":"Hermann Hesse source person OL76437A and exact-ISBN KB authority p068404956 share Wikidata Q25973, ISNI0000000121296240 and VIAF41841418. This resolves Hermann/Hermann Karl without name-only matching. Exact DeSteppewolf paperback9789023411239; existing Work retained."},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://openlibrary.org/works/OL872773W","https://data.bibliotheken.nl/id/nbt/p078216117","https://data.bibliotheken.nl/id/nbt/p085356573","https://data.bibliotheken.nl/id/nbt/p371614406","https://data.bibliotheken.nl/id/nbt/p830736387","https://data.bibliotheken.nl/id/nbt/p841089167"]},