-review-020.json","sources":["https://openlibrary.org/works/OL872773W","https://data.bibliotheken.nl/id/nbt/p078216117","https://data.bibliotheken.nl/id/nbt/p085356573","https://data.bibliotheken.nl/id/nbt/p371614406","https://data.bibliotheken.nl/id/nbt/p830736387","https://data.bibliotheken.nl/id/nbt/p841089167"]},{"type":"cover_front_review","sha256":"7f45914a09af1bbb71c532861b731a363cae9c7384b66e12b2b4c504d6715705","cover_id":6868165,"reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-003.jpg. Hermann Hesse; De steppewolf. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"cover_url":"https://covers.openlibrary.org/b/id/6868165-L.jpg?default=false","edition_id":987213008,"bound_title":"De Steppewolf","reviewed_at":"2026-11-02T21:06:36.091+00:00","bound_isbn13":"9789023411239","evidence_url":"https://data.bibliotheken.nl/id/nbt/p078216117","review_batch":"nl-scale-20261102-014","review_status":"approved","bound_language":"dut","card_cover_url":"https://covers.openlibrary.org/b/id/6868165-M.jpg?default=false","bound_author_id":987313002}'::jsonb as exact union all select 'catalog_work_descriptions:9' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987113005 and t.language='nl')='{"text":"Hoe kan het heelal zijn ontstaan en wat bedoelen we wanneer we spreken over werkelijkheid? Het grote ontwerp verkent die vragen aan de hand van natuurkundige modellen. Daarbij komen onder meer verschillende mogelijke heelallen, de rol van waarneming en pogingen tot een overkoepelende theorie aan bod. De auteurs bespreken wat zulke benaderingen kunnen betekenen voor traditionele verklaringen van de kosmos. Het boek presenteert hun kijk op deze wetenschappelijke en filosofische vraagstukken, zonder dat de lezer zelf de wiskundige uitwerking hoeft te volgen.","work_id":987113005,"